func (p *ImageProcessor) ApplyFilters(layers []imageProcessing.ImageLayer) error {
	stepIdx := 0
	batchLimit := 8
	wg := new(sync.WaitGroup)
	errChan := make(chan error, 1)

	for {
		low, high := partitionBatch(stepIdx, batchLimit, len(layers))
		if low == high {
			break
		}

		wg.Add(1)
		go func() {
			defer wg.Done()
			currentBatch := layers[low:high]

			procCtx, stop := context.WithDeadline(context.Background(), time.Now().Add(5*time.Second))
			defer stop()
			procCtx = imageProcessing.WithProfile(procCtx)
			job := imageProcessing.FilterJob{Layers: currentBatch}

			result, status, err := p.engine.Render(procCtx, job, *imageProcessing.NewRenderOptions())
			if err != nil {
				errChan <- fmt.Errorf("render operation failed: %w", err)
				return
			}

			if status.Code != 200 {
				errChan <- fmt.Errorf("render operation failed: %d", status.Code)
				return
			}

			if len(result.Warnings) > 0 {
				warningJson, err := yaml.Marshal(result)
				if err != nil {
					errChan <- fmt.Errorf("could not encode warnings: %w", err)
					return
				}
				errChan <- fmt.Errorf("render completed with warnings: %s", warningJson)
				return
			}
			errChan <- nil
		}()

		stepIdx++
	}

	wg.Wait()
	close(errChan)
	return <-errChan
}

