func expandZip(z *zip.Reader) ref.Val {
	var files []map[string]interface{}
	for _, f := range z.File {
		rc, err := f.Open()
		if err != nil {
			return types.NewErr("zip: %s", err)
		}
		var buf bytes.Buffer
		_, err = io.Copy(&buf, rc)
		if err != nil {
			return types.NewErr("zip: %s", err)
