		files = append(files, map[string]interface{}{
			"Name":     fh.Name,
			"Comment":  fh.Comment,
			"IsDir":    fi.IsDir(),
			"Size":     fi.Size(),
			"NonUTF8":  fh.NonUTF8,
			"Modified": fh.Modified,
			"CRC32":    fh.CRC32,
			"Extra":    fh.Extra,
			"Data":     buf.Bytes(),
		})
	}
	return types.DefaultTypeAdapter.NativeToValue(map[string]interface{}{
		"File":    files,
		"Comment": z.Comment,
	})
}

