def _categorize_elements(self):
        classifications = []
        element_map = OrderedDict()
        side_components = []
        counter = itertools.count(start=1)
        for element in self.analysis_targets or []:
            if isinstance(element.component, BaseNode):
                tag = element.assemble_tag(self, self.context)
                classifications.append((element.component.path.attribute, element.component))
            elif isinstance(element.component, Pointer):
                tag = element.assemble_tag(self, self.context)
            else:
                tag = f"__group{next(counter)}"
                classifications.append((tag, element.component))
            if element.priority_flag or element.exclusion_flag:
                flag_tag = f"__group{next(counter)}"
                rule = Conditional(Compare(element.component, Equal, None), result=Constant(True))
                side_components.append((flag_tag, Selector(rule, default=Constant(False))))
                element_map[flag_tag] = REVERSE if element.priority_flag else STANDARD
            element_map[tag] = REVERSE if element.inverted else STANDARD
        return tuple(classifications), element_map, tuple(side_components)

