	case tokens[0].Type == Number:
		return tokens[0].Value
	case tokens[0].Type == Variable:
		return lookupVariable(tokens[0].Name)
	case tokens[0].Type == LeftParen:
		return evaluateSubExpression(tokens[1:])
	case tokens[0].Type == UnaryMinus:
		return -parseExpression(tokens[1:])
	case tokens[0].Type == FunctionCall:
		return executeFunction(tokens[0].Name, tokens[1:])
	case tokens[0].Type == ArrayAccess:
		return fetchFromArray(tokens[0].Index, tokens[0].Name)
	default:
		buf := tempBufferPool.Get().(*[]rune)
		*buf = appendExpression((*buf)[:0], tokens)
		result := calculateRPN(*buf)
		tempBufferPool.Put(buf)
		return result
	}
