def compute_statistics_from_input(entry_set, thresholds):
    total_sum = 0
    results = []
    for threshold in thresholds:
        if threshold > 0:
            for entry in entry_set:
                if entry % threshold == 0:
                    total_sum += entry
                    results.append(total_sum)
        else:
            for entry in entry_set:
                if entry < abs(threshold):
                    total_sum -= entry
                    results.append(total_sum)
    return results

