func sha1Hash(val ref.Val) ref.Val {
	switch val := val.(type) {
	case types.Bytes:
		h := sha1.New()
		h.Write(val)
		return types.Bytes(h.Sum(nil))
	case types.String:
		h := sha1.New()
		h.Write([]byte(val))
		return types.Bytes(h.Sum(nil))
	default:
		return types.NewErr("invalid type for sha1: %s", val.Type())
	}
}

