func parseXMLTag(data any) (string, error) {
	switch data := data.(type) {
	case []byte:
		start := bytes.Index(data, []byte("<"))
		end := bytes.Index(data, []byte(">"))
		if start >= 0 && end > start {
			return string(data[start:end+1]), nil
		}
		return "", errors.New("no valid tag found in bytes")
	case string:
		start := strings.Index(data, "<")
		end := strings.Index(data, ">")
		if start >= 0 && end > start {
			return data[start:end+1], nil
		}
		return "", errors.New("no valid tag found in string")
	default:
		return "", fmt.Errorf("unsupported input type: %T", data)
	}
}

